import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"0003. GitHub Pages project sites with a 404.html SPA fallback","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0003-github-pages-deployment.md","filePath":"decisions/0003-github-pages-deployment.md"}`),a={name:`decisions/0003-github-pages-deployment.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="_0003-github-pages-project-sites-with-a-404-html-spa-fallback" tabindex="-1" dir="auto">0003. GitHub Pages project sites with a 404.html SPA fallback <a class="header-anchor" href="#_0003-github-pages-project-sites-with-a-404-html-spa-fallback" aria-label="Permalink to “0003. GitHub Pages project sites with a 404.html SPA fallback”">​</a></h1><ul><li dir="auto">Status: accepted (deployment mechanism superseded by 0004)</li><li dir="auto">Date: 2026-09-22</li></ul><h2 id="context" tabindex="-1" dir="auto">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p dir="auto">The sites are static and hosted on GitHub Pages project sites (<code>&lt;user&gt;.github.io/&lt;repo&gt;/</code>) with no custom domain. Pages has no rewrites.</p><h2 id="decision" tabindex="-1" dir="auto">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li dir="auto">Vite <code>base</code> comes from the <code>BASE_PATH</code> env var (deploy workflow: <code>/&lt;repo&gt;/</code>), and the router uses <code>basename={import.meta.env.BASE_URL}</code>.</li><li dir="auto">Each build copies <code>index.html</code> to <code>404.html</code>, so deep links load the SPA.</li><li dir="auto">One Pages site per repo: <code>site</code> at <code>/</code>, Storybook at <code>/storybook/</code>.</li></ul><h2 id="consequences" tabindex="-1" dir="auto">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li dir="auto">Deep links return HTTP 404 status with the right content. That&#39;s fine for users; for SEO-critical pages, prerendering would be needed later.</li><li dir="auto">Hard-coded absolute paths (<code>/img.png</code>) break under the base path. Use <code>BASE_URL</code>.</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};